CREATE TABLE public.tutor_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, course_id uuid REFERENCES public.courses(id) ON DELETE SET NULL, title text NOT NULL DEFAULT 'New chat', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tutor_threads TO authenticated;
GRANT ALL ON public.tutor_threads TO service_role;
ALTER TABLE public.tutor_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own threads" ON public.tutor_threads FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.tutor_threads FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE INDEX ON public.tutor_threads (user_id, updated_at DESC);
CREATE TABLE public.tutor_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.tutor_threads(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('user','assistant')), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tutor_messages TO authenticated;
GRANT ALL ON public.tutor_messages TO service_role;
ALTER TABLE public.tutor_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own messages" ON public.tutor_messages FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE INDEX ON public.tutor_messages (thread_id, created_at);